def set_run_font(run, size=14, bold=False):
    run.font.name = "Times New Roman"
    run._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    run._element.rPr.rFonts.set(qn("w:ascii"), "Times New Roman")
    run._element.rPr.rFonts.set(qn("w:hAnsi"), "Times New Roman")
    run.font.size = Pt(size)
    run.bold = bold


def add_page_number(header):
    paragraph = header.paragraphs[0]
    paragraph.alignment = WD_ALIGN_PARAGRAPH.RIGHT
    run = paragraph.add_run()
    set_run_font(run)

    fld_char1 = OxmlElement('w:fldChar')
    fld_char1.set(qn('w:fldCharType'), 'begin')
    instr_text = OxmlElement('w:instrText')
    instr_text.set(qn('xml:space'), 'preserve')
    instr_text.text = " PAGE "
    fld_char2 = OxmlElement('w:fldChar')
    fld_char2.set(qn('w:fldCharType'), 'end')
    run._r.append(fld_char1)
    run._r.append(instr_text)
    run._r.append(fld_char2)


def add_toc(paragraph):
    run = paragraph.add_run()
    set_run_font(run)
    fld_char_begin = OxmlElement('w:fldChar')
    fld_char_begin.set(qn('w:fldCharType'), 'begin')
    instr_text = OxmlElement('w:instrText')
    instr_text.set(qn('xml:space'), 'preserve')
    instr_text.text = ' TOC \\o "1-2" \\h \\z \\u '
    fld_char_separate = OxmlElement('w:fldChar')
    fld_char_separate.set(qn('w:fldCharType'), 'separate')
    text = OxmlElement('w:t')
    text.text = "Зміст буде сформовано автоматично після оновлення полів у Microsoft Word."
    fld_char_end = OxmlElement('w:fldChar')
    fld_char_end.set(qn('w:fldCharType'), 'end')
    run._r.append(fld_char_begin)
    run._r.append(instr_text)
    run._r.append(fld_char_separate)
    run._r.append(text)
    run._r.append(fld_char_end)


def apply_document_defaults(document):
    section = document.sections[0]
    section.top_margin = Mm(20)
    section.bottom_margin = Mm(20)
    section.left_margin = Mm(30)
    section.right_margin = Mm(10)
    section.different_first_page_header_footer = True
    add_page_number(section.header)

    normal = document.styles["Normal"]
    normal.font.name = "Times New Roman"
    normal._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
    normal.font.size = Pt(14)
    normal.paragraph_format.line_spacing = 1.5
    normal.paragraph_format.space_after = Pt(0)
    normal.paragraph_format.space_before = Pt(0)
    normal.paragraph_format.first_line_indent = Cm(1.25)

    for style_name in ["Heading 1", "Heading 2"]:
        style = document.styles[style_name]
        style.font.name = "Times New Roman"
        style._element.rPr.rFonts.set(qn("w:eastAsia"), "Times New Roman")
        style.font.size = Pt(14)
        style.font.bold = True
        style.paragraph_format.line_spacing = 1.5
        style.paragraph_format.space_before = Pt(0)
        style.paragraph_format.space_after = Mm(20)
        style.paragraph_format.first_line_indent = Cm(0)


def add_title_page(document):
    for idx, line in enumerate(TITLE_PAGE_LINES):
        p = document.add_paragraph()
        if idx < 3 or line in {"ЗВІТ", "ПРО ПЕРЕДДИПЛОМНУ ПРАКТИКУ", "[МІСТО] – [РІК]"}:
            p.alignment = WD_ALIGN_PARAGRAPH.CENTER
        else:
            p.alignment = WD_ALIGN_PARAGRAPH.LEFT
        if line == "":
            continue
        run = p.add_run(line)
        set_run_font(run, bold=line in {"ЗВІТ", "ПРО ПЕРЕДДИПЛОМНУ ПРАКТИКУ"})
    document.add_page_break()


def add_heading(document, text, level=1):
    p = document.add_paragraph(style=f"Heading {level}")
    p.alignment = WD_ALIGN_PARAGRAPH.LEFT
    p.paragraph_format.first_line_indent = Cm(0)
    run = p.add_run(text.upper())
    set_run_font(run, bold=True)
    return p


def add_body_paragraph(document, text):
    p = document.add_paragraph(style="Normal")
    p.alignment = WD_ALIGN_PARAGRAPH.JUSTIFY
    p.paragraph_format.first_line_indent = Cm(1.25)
    parts = text.split("\n")
    for i, part in enumerate(parts):
        run = p.add_run(part)
        set_run_font(run)
        if i != len(parts) - 1:
            run.add_break()
    return p


def build_document():
    document = Document()
    apply_document_defaults(document)
    add_title_page(document)

    add_heading(document, "ЗМІСТ", level=1)
    toc_paragraph = document.add_paragraph(style="Normal")
    toc_paragraph.alignment = WD_ALIGN_PARAGRAPH.LEFT
    toc_paragraph.paragraph_format.first_line_indent = Cm(0)
    add_toc(toc_paragraph)
    document.add_page_break()

    for title, paragraphs in REPORT:
        level = 1 if not any(title.startswith(prefix) for prefix in ["2.1", "2.2", "3.1", "3.2", "3.3", "3.4", "3.5", "4.1", "4.2", "4.3", "4.4"]) else 2
        add_heading(document, title, level=level)
        for paragraph in paragraphs:
            add_body_paragraph(document, paragraph)

    document.save(OUTPUT)


if __name__ == "__main__":
    build_document()
    print(OUTPUT)
